#include <deque>
#include <iostream>

int main() {
  std::deque<int> d{1, 2, 3};
  int& r = d[1];
  for (int i = 0; i < 1000; ++i) {
    d.push_back(i);
    d.push_front(-i);
  }
  r = 99;
  std::cout << d[1001] << '\n';
}

