}

#include <cstdio>
#include <vector>

struct S {
  S() = default;
  S(const S&) { std::puts("copy"); }
  S(S&&) { std::puts("move"); }  // not noexcept
};

int main() {
  std::vector<S> v;
  v.reserve(4);
  while (v.size() < v.capacity()) v.emplace_back();
  std::puts("grow");
  v.emplace_back();
}

